$(function(){var n=$("#NwazetCommerceAttribute_AttributeValueRecords > li.option").length;$("#NwazetCommerceAttribute_AddAttributeValue").click(function(t){t.preventDefault();var i=$("#valueTemplate").html();$("#NwazetCommerceAttribute_AttributeValueRecords").append(Mustache.render(i,{index:n,sort:n+1})).last().find(".option-name input[type=text]").focus();n++});$("#NwazetCommerceAttribute_AttributeValueRecords").on("click",".nwazet-remove-attribute-value",function(n){n.preventDefault();$(this).parents("li").remove()});$("#NwazetCommerceAttribute_AttributeValueRecords").sortable({update:function(){$.each($(this).children("li"),function(){var n=$(this);n.find("input[name$=SortOrder]").val(n.index())})}})});